use fieldkin::{DataType, Field, Table, Matcher, algorithms::{Coma, strings::{trigram_similarity, tokens_similarity}}};
use std::{alloc::{GlobalAlloc, Layout, System}, hint::black_box, sync::atomic::{AtomicUsize,Ordering}, time::Instant};
struct Counter;
static ALLOCS:AtomicUsize=AtomicUsize::new(0);
#[global_allocator] static ALLOCATOR: Counter = Counter;
unsafe impl GlobalAlloc for Counter {
 unsafe fn alloc(&self,l:Layout)->*mut u8 {ALLOCS.fetch_add(1,Ordering::Relaxed); unsafe{System.alloc(l)}}
 unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}
 unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{ALLOCS.fetch_add(1,Ordering::Relaxed);unsafe{System.realloc(p,l,n)}}
}
fn names(case:&str,n:usize,side:usize)->Vec<String>{(0..n).map(|i| match case {
 "short"=>format!("{}_{}",if side==0{"measure"}else{"attribute"},i),
 "unicode"=>format!("É界🙂İ_{}_{}",if side==0{"μέτρο"}else{"μέτρηση"},i),
 "long"=>format!("{}_{}_{}",if side==0{"measure"}else{"attribute"},"account_ownership_history".repeat(5),i),
 "tiny"=>format!("{}{}",(b'a'+(i/26)as u8) as char,(b'a'+(i%26)as u8) as char),
 _=>panic!("unknown case"),
 }).collect()}
fn main(){let args:Vec<_>=std::env::args().collect();let case=&args[1];let n=args[2].parse().unwrap(); let a=names(case,n,0);let b=names(case,n,1);
for (name,f) in [("trigram",trigram_similarity as fn(&str,&str)->f64),("tokens",tokens_similarity)] { ALLOCS.store(0,Ordering::Relaxed); let start=Instant::now();let mut sum=0.; for x in &a {for y in &b{sum+=black_box(f(x,y));}}let elapsed=start.elapsed();let count=ALLOCS.load(Ordering::Relaxed);println!("{name} ms={} allocations={count} sum={sum}",elapsed.as_secs_f64()*1000.);}
let tables:Vec<_>=[a,b].into_iter().enumerate().map(|(i,v)|Table::new(format!("table{i}"),v.into_iter().map(|name|Field{name,data_type:DataType::Text,samples:vec![]}).collect()).unwrap()).collect(); ALLOCS.store(0,Ordering::Relaxed);let start=Instant::now();let result=Coma::default().get_matches(&tables[0],&tables[1]).unwrap();let elapsed=start.elapsed();let count=ALLOCS.load(Ordering::Relaxed);println!("COMA ms={} allocations={count} matches={}",elapsed.as_secs_f64()*1000.,result.len());
}
